const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Bs '+Number(n).toLocaleString('es-BO',{minimumFractionDigits:2});
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/La_Paz',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let day=today,view='Agenda',filter='Todos',role='Propietario',search='',cashOpen=false,opening=0,closed=false;
const barbers=['Mateo Rojas','Diego Vargas','Nicolás Cruz'];
const services=[{name:'Corte clásico',price:40,duration:30},{name:'Corte + barba',price:65,duration:60},{name:'Perfilado de barba',price:30,duration:30}];
let clients=['Andrés Salazar','Gabriel Flores','Sebastián Ríos','Luis Mendoza','Daniel Castro','Joaquín Pérez'].map((name,i)=>({id:i+1,name,phone:''}));
let appointments=[{id:1,client:1,barber:0,time:'09:00',service:0,status:'Completada',paid:40,method:'Efectivo'},{id:2,client:2,barber:0,time:'10:30',service:1,status:'En servicio',paid:0},{id:3,client:3,barber:1,time:'09:30',service:1,status:'Confirmada',paid:0},{id:4,client:4,barber:1,time:'11:00',service:0,status:'Confirmada',paid:0},{id:5,client:5,barber:2,time:'10:00',service:0,status:'Completada',paid:0},{id:6,client:6,barber:2,time:'11:30',service:2,status:'Pendiente',paid:0}].map(a=>({...a,date:today,price:services[a.service].price,duration:services[a.service].duration}));
let movements=[{date:today,amount:40,type:'Efectivo',note:'Cobro · Andrés Salazar'}],promos=[];
const icons={Configuración:'M12 3v3m0 12v3M3 12h3m12 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',Agenda:'M8 2v4m8-4v4M3 9h18M4 4h16v17H4z',Clientes:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 8m3 9v-2a4 4 0 0 0-3-4',Servicios:'m4 4 16 16M4 20 20 4M6 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6m0 12a3 3 0 1 0 0-6 3 3 0 0 0 0 6',Caja:'M3 6h18v15H3zM7 6V3h10v3M3 12h18M9 16h6',Afluencia:'M4 20V10m6 10V4m6 16v-7m6 7V1',Promociones:'M3 3h8l10 10-8 8L3 11zM7 7h.01',Equipo:'M4 21v-4h16v4M8 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10'};
function allowed(){return role==='Barbero'?['Agenda','Clientes','Servicios']:role==='Recepción'?['Agenda','Clientes','Servicios','Venta de productos','Caja']:['Agenda','Clientes','Servicios','Venta de productos','Caja','Estadísticas','Afluencia','Promociones','Inventario','Comisiones','Equipo','Configuración']}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function navigate(v){if(!allowed().includes(v))return;view=v;search='';render()}
function base_render(){if(!allowed().includes(view))view='Agenda';$('#nav').innerHTML=allowed().map(n=>`<button class="${view===n?'active':''}" onclick="navigate('${n}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[n]}"/></svg>${n}</button>`).join('');$('#crumb').textContent=view;$('#roleLabel').textContent=role;({'Venta de productos':productSalesPage,Agenda:agenda,Clientes:clientPage,Servicios:servicePage,Caja:cashPage,Afluencia:heatPage,Promociones:promoPage,Equipo:teamPage,Configuración:setupPage,Estadísticas:statsPage,Inventario:inventoryPage,Comisiones:commissionPage}[view])()}
function heading(title,sub,action=''){return `<div class="pagehead"><div><span class="eyebrow">TU BARBERÍA, EN ORDEN</span><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`}
function stat(label,value,detail){return `<div class="stat"><label>${label}</label><strong>${value}</strong><small>${detail}</small></div>`}
function name(a){return clients.find(c=>c.id===a.client)?.name||'Cliente'}
function minutes(t){const [h,m]=t.split(':').map(Number);return h*60+m}function clock(m){return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')}
function changeDay(n){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);day=d.toISOString().slice(0,10);render()}
function field(label,content){return `<label class="field">${label}${content}</label>`}function input(n,type='text',value='',extra=''){return `<input name="${n}" type="${type}" value="${esc(value)}" ${extra}>`}
function closeModal(){$('#modal').close()}
function finish(msg){closeModal();render();notify(msg)}
function clientPage(){const rows=clients.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())||c.phone.includes(search));$('#main').innerHTML=heading('Clientes','Cada visita, una relación que crece.','<button class="primary" onclick="clientForm()">＋ Nuevo cliente</button>')+`<section class="panel"><div class="panelhead"><h2>${clients.length} clientes</h2><input type="search" aria-label="Buscar cliente" placeholder="Buscar nombre o teléfono" value="${esc(search)}" oninput="search=this.value;clientRows()" id="clientSearch"></div><div class="tablewrap"><table><thead><tr><th>Cliente</th><th>Teléfono</th><th>Atenciones</th><th>Próxima cita</th></tr></thead><tbody id="clientRows"></tbody></table></div></section>`;clientRows()}
$('#role').onchange=e=>{role=e.target.value;filter='Todos';render()};$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
// Version 2: richer workflows, still explicitly a demonstration until backend activation.
let calendarMode='day',statusFilter='Todas',historyLog=[],reportFrom=today,reportTo=today,heatMode='attended';
let schedules=barbers.map(()=>({start:'09:00',end:'18:00',breakStart:'13:00',breakEnd:'14:00',days:[1,2,3,4,5,6],active:true}));
let cashSessions=[],currentCashId=null;
services.forEach(s=>{s.active=true;s.prep=0});
appointments.forEach(a=>{a.serviceName=services[a.service].name;a.prep=0});
movements[0].appointment=1;movements[0].id=1;
function logAction(title,entity=null){historyLog.unshift({time:new Date().toISOString(),title,entity,role})}
function activeStaff(){return barbers.map((name,id)=>({name,id})).filter(b=>schedules[b.id].active)}
function dayOf(d){return new Date(d+'T12:00:00').getDay()}
function availableMinutes(d,b){return ranges(d,b).reduce((sum,[a,z])=>sum+z-a,0)}
function visible(){return appointments.filter(a=>a.date===day&&(role!=='Barbero'||a.barber===0)&&(filter==='Todos'||a.barber===+filter)&&(statusFilter==='Todas'||a.status===statusFilter))}
function agenda(){const list=visible(),scoped=agendaScope();const pending=scoped.filter(a=>!['Cancelada','No asistió'].includes(a.status)&&a.paid<a.price);$('#main').innerHTML=heading('La agenda de tu barbería',new Date(day+'T12:00:00').toLocaleDateString('es-BO',{weekday:'long',day:'numeric',month:'long'}),'<div class="buttons"><button onclick="clientForm()">Nuevo cliente</button><button class="primary" onclick="bookingForm()">＋ Nueva cita</button></div>')+`<div class="stats">${stat(calendarMode==='week'?'Citas de la semana':'Citas del día',scoped.length,'Período y equipo seleccionados · todos los estados')}${stat('En atención',scoped.filter(a=>a.status==='En servicio').length,'En servicio en el período seleccionado')}${stat('Por confirmar',scoped.filter(a=>a.status==='Pendiente').length,'Citas pendientes de confirmación')}${stat(role==='Barbero'?'Atenciones completadas':'Pendiente de cobrar',role==='Barbero'?scoped.filter(a=>a.status==='Completada').length:money(pending.reduce((n,a)=>n+a.price-a.paid,0)),role==='Barbero'?'Servicios finalizados':pending.length+' citas con saldo, incluidas reservas')}</div>${reminderBanner()}<div class="toolbar"><div class="segmented"><button class="${calendarMode==='day'?'selected':''}" onclick="calendarMode='day';render()">Día</button><button class="${calendarMode==='week'?'selected':''}" onclick="calendarMode='week';render()">Semana</button></div><div class="filters"><button onclick="changeDay(calendarMode==='week'?-7:-1)" aria-label="Anterior">‹</button><button onclick="day=today;render()">Hoy</button><input aria-label="Fecha" type="date" value="${day}" onchange="day=this.value||today;render()"><button onclick="changeDay(calendarMode==='week'?7:1)" aria-label="Siguiente">›</button></div></div>${availabilityPanel()}<section class="panel"><div class="panelhead"><h2>${calendarMode==='day'?'Citas por profesional':'Tu semana de un vistazo'}</h2><div class="filters">${role!=='Barbero'?`<select aria-label="Barbero" onchange="filter=this.value;render()"><option value="Todos">Todo el equipo</option>${barbers.map((b,i)=>`<option value="${i}" ${filter===String(i)?'selected':''}>${esc(b)}</option>`).join('')}</select>`:''}<select aria-label="Estado de cita" onchange="statusFilter=this.value;render()">${['Todas','Pendiente','Confirmada','Cliente presente','En servicio','Completada','Cancelada','No asistió'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select></div></div>${calendarMode==='week'?weekBoard():`<div class="board" style="grid-template-columns:repeat(${role==='Barbero'||filter!=='Todos'?1:barbers.length},minmax(0,1fr))">${barbers.map((b,i)=>role==='Barbero'&&i!==0||filter!=='Todos'&&+filter!==i?'':`<div class="lane"><div class="barber"><span class="avatar">${esc(b.split(' ').map(n=>n[0]).join(''))}</span><div><b>${esc(b)}</b><small>${ranges(day,i).length? schedules[i].start+'–'+schedules[i].end:'Día libre'} · ${list.filter(a=>a.barber===i).length} citas</small></div></div>${list.filter(a=>a.barber===i).sort((a,b)=>a.time.localeCompare(b.time)).map(bookingCard).join('')||'<div class="empty">Agenda despejada<small>Las nuevas citas aparecerán aquí.</small></div>'}</div>`).join('')}</div>`}<div class="agendaBottom"><span>Las duraciones incluyen el tiempo de preparación configurado.</span><span>Hora de Bolivia · Bs</span></div></section>`}
function weekBoard(){const start=new Date(day+'T12:00:00');start.setDate(start.getDate()-((start.getDay()+6)%7));return '<div class="weekwrap"><div class="weekgrid">'+Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const date=d.toISOString().slice(0,10);const items=appointments.filter(a=>a.date===date&&(role!=='Barbero'||a.barber===0)&&(filter==='Todos'||a.barber===+filter)&&(statusFilter==='Todas'||a.status===statusFilter));return `<div class="weekcol ${date===today?'current':''}"><button class="weekdate" onclick="day='${date}';calendarMode='day';render()">${d.toLocaleDateString('es-BO',{weekday:'short'})}<b>${d.getDate()}</b></button>${items.sort((a,b)=>a.time.localeCompare(b.time)).map(bookingCard).join('')||'<div class="empty">Sin citas</div>'}</div>`}).join('')+'</div></div>'}
function base_bookingCard(a){const next={'Pendiente':'Confirmar','Confirmada':'Llegó','Cliente presente':'Atender','En servicio':'Completar'};return `<article class="booking ${a.status==='En servicio'?'service':a.status==='Completada'?'done':['Cancelada','No asistió'].includes(a.status)?'cancelled':''}"><div class="time"><span>${esc(a.time)}–${clock(minutes(a.time)+a.duration+(a.prep||0))}</span><span class="badge">${esc(a.status)}</span></div><h3>${esc(name(a))}</h3><p>${esc(a.serviceName||services[a.service].name)} · ${a.duration} min${a.prep?' + '+a.prep+' preparación':''}${calendarMode==='week'?'<br>'+esc(barbers[a.barber]):''}</p><div class="bookingfoot"><b>${money(a.price)}</b><span>${role!=='Barbero'&&!['Cancelada','No asistió'].includes(a.status)?`<button onclick="paymentForm(${a.id})">Cobrar</button>`:''}${a.paid>=a.price?'<span class="badge">Pagado</span>':''} <button aria-label="Detalles de ${esc(name(a))}" onclick="detail(${a.id})">•••</button></span></div></article>`}
function base_advance(id){const a=appointments.find(a=>a.id===id),next={'Pendiente':'Confirmada','Confirmada':'Cliente presente','Cliente presente':'En servicio','En servicio':'Completada'};if(next[a.status]){a.status=next[a.status];logAction('Estado: '+a.status,id)}render();notify(a.status==='Completada'?'Atención completada. Falta registrar el cobro si corresponde.':'Estado actualizado')}
function base_detail(id){const a=appointments.find(a=>a.id===id),c=clients.find(c=>c.id===a.client);const open=!['Completada','Cancelada','No asistió'].includes(a.status);modal('Detalle e historial',`<h3>${esc(name(a))}</h3><p class="muted">${esc(a.serviceName)} · ${esc(barbers[a.barber])}<br>${esc(a.date)} · ${esc(a.time)} · ${esc(a.status)}</p><div class="summarystrip"><span>Total: <b>${money(a.price)}</b></span><span>Saldo: <b>${money(a.price-a.paid)}</b></span></div><div class="buttons" style="margin:18px 0">${open?`<button type="button" onclick="closeModal();bookingForm(${id})">Editar / reprogramar</button>`:''}${c?.phone?`<button type="button" onclick="whatsapp(${id})">Preparar WhatsApp</button>`:''}<button type="button" onclick="closeModal();clientDetail(${a.client})">Ver cliente</button></div>${open?field('Acción',`<select name="action"><option value="none">Conservar cita</option><option>Cancelada</option><option>No asistió</option></select>`)+field('Motivo de cancelación o ausencia',input('reason','text','','maxlength="180"')):''}<div class="history">${historyLog.filter(l=>l.entity===id).map(l=>`<p><strong>${esc(l.title)}</strong>${new Date(l.time).toLocaleString('es-BO',{timeZone:'America/La_Paz'})} · ${esc(l.role)}</p>`).join('')||'<p>Registro inicial.</p>'}</div>`,f=>{const state=f.get('action');if(state&&state!=='none'){if(!f.get('reason').trim())throw Error('Escribe el motivo del cambio.');a.status=state;logAction(state+': '+f.get('reason'),id)}finish('Detalle guardado')})}
function whatsapp(id){const a=appointments.find(x=>x.id===id);if(!a)return notify('La cita ya no está disponible.');const c=clients.find(x=>x.id===a.client);let phone=(c?.phone||'').replace(/\D/g,'');if(phone.length===8)phone='591'+phone;if(phone.length<10||phone.length>15)return notify('Agrega o revisa el teléfono del cliente, incluido el código de país.');const msg=reminderMessage(a);modal('Revisar recordatorio',`<div class="quote"><span>${esc(c.name)} · ${esc(barbers[a.barber])}</span><strong>${timeLabel(a.time)}</strong><small>${displayDate(a.date)} · hora de Bolivia</small></div><p class="formhint">Estos son los datos guardados de esta cita. Si la hora no es correcta, reprograma y guarda antes de preparar el mensaje.</p><p class="message-preview">${esc(msg)}</p><div class="buttons"><button type="button" onclick="closeModal();bookingForm(${id})">Corregir cita</button><a class="primary whatsapp-link" href="https://wa.me/${phone}?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a></div><p class="formhint">Revisa el texto en WhatsApp antes de enviarlo. Abrir el enlace no registra el mensaje como enviado.</p>`,()=>closeModal())}
function timeLabel(time){if(!time)return 'Hora no registrada';const [h,m]=time.split(':').map(Number);return (h%12||12)+':'+String(m).padStart(2,'0')+' '+(h>=12?'PM':'AM')}
function displayDate(date){if(!date)return 'Fecha no registrada';return date.split('-').reverse().join('/')}
function reminderMessage(a){return `Hola, ${name(a)}. Te recordamos tu cita en The Barber Haircuts & Shaves el ${displayDate(a.date)} a la(s) ${timeLabel(a.time)} (hora de Bolivia), con ${barbers[a.barber]}. Servicio: ${a.serviceName}. Total: ${money(a.price)}. Abonado: ${money(a.paid)}. Saldo: ${money(round(a.price-a.paid))}. ¿Nos confirmas tu asistencia?`}

function clientRows(){$('#clientRows').innerHTML=clients.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())||c.phone.includes(search)).map(c=>`<tr><td><button style="border:0;padding:0;text-align:left" onclick="clientDetail(${c.id})">${esc(c.name)}</button></td><td>${esc(c.phone)||'Sin registrar'}</td><td>${appointments.filter(a=>a.client===c.id&&a.status==='Completada').length}</td><td>${appointments.filter(a=>a.client===c.id&&['Confirmada','Pendiente'].includes(a.status)).map(a=>a.date+' · '+a.time).join(', ')||'Sin cita pendiente'}</td></tr>`).join('')||'<tr><td colspan="4">No hay coincidencias.</td></tr>'}
function clientForm(id=null){const old=clients.find(c=>c.id===id);modal(old?'Editar cliente':'Nuevo cliente',field('Nombre',input('name','text',old?.name||'','required maxlength="80"'))+field('Teléfono (opcional)',input('phone','tel',old?.phone||'','maxlength="20"'))+field('Preferencias de corte',`<textarea name="notes" maxlength="300">${esc(old?.notes||'')}</textarea>`)+`<label class="inlinecheck"><input type="checkbox" name="consent" ${old?.consent?'checked':''}>Aceptó recibir promociones</label><p class="formhint">Registra el consentimiento solo si el cliente lo otorgó. Los recordatorios de citas son independientes.</p>`,f=>{const n=f.get('name').trim(),p=f.get('phone').trim();if(!n)throw Error('Escribe el nombre.');if(clients.some(c=>c.id!==id&&(c.name.toLowerCase()===n.toLowerCase()||p&&c.phone.replace(/\D/g,'')===p.replace(/\D/g,''))))throw Error('Hay un posible duplicado con ese nombre o teléfono.');const data={name:n,phone:p,notes:f.get('notes').trim(),consent:f.has('consent')};if(old)Object.assign(old,data);else clients.push({id:uuidNumber(),...data});logAction(old?'Cliente editado':'Cliente creado');finish('Cliente guardado')})}
function clientDetail(id){const c=clients.find(c=>c.id===id);modal('Ficha del cliente',`<h3>${esc(c.name)}</h3><p class="muted">${esc(c.phone)||'Sin teléfono'}<br>${c.consent?'Acepta promociones':'Sin consentimiento promocional'}</p><p>${esc(c.notes)||'Sin preferencias registradas.'}</p><button type="button" onclick="closeModal();clientForm(${id})">Editar datos</button><h3 class="subhead">Historial de visitas</h3><div class="history">${appointments.filter(a=>a.client===id).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<p><strong>${esc(a.date)} · ${esc(a.serviceName)}</strong>${esc(a.status)} · ${esc(barbers[a.barber])} · ${money(a.price)}</p>`).join('')||'<p>Todavía no hay visitas.</p>'}</div>`,()=>closeModal())}
function servicePage(){$('#main').innerHTML=heading('Servicios y precios','Define cada servicio una vez; las citas guardan su precio original.',role==='Propietario'?'<button class="primary" onclick="serviceForm()">＋ Nuevo servicio</button>':'')+`<div class="cards">${services.map((s,i)=>`<article class="card"><span class="badge">${s.active?'Activo':'Desactivado'}</span><h2 style="margin-top:17px">${esc(s.name)}</h2><strong class="price">${money(s.price)}</strong><p>${s.duration} minutos de atención<br>${s.prep||0} minutos de preparación</p>${role==='Propietario'?`<button onclick="serviceForm(${i})">Editar servicio</button>`:''}</article>`).join('')}</div>`}
function serviceForm(id=null){if(role!=='Propietario')return;const s=services[id];modal(s?'Editar servicio':'Nuevo servicio',field('Nombre',input('name','text',s?.name||'','required maxlength="80"'))+`<div class="two">${field('Precio (Bs)',input('price','number',s?.price??40,'required min="0" max="100000" step="0.01"'))}${field('Duración (min)',input('duration','number',s?.duration??30,'required min="5" max="480" step="5"'))}</div>`+field('Preparación después del servicio (min)',input('prep','number',s?.prep??0,'required min="0" max="60" step="5"'))+`<label class="inlinecheck"><input type="checkbox" name="active" ${!s||s.active?'checked':''}>Disponible para nuevas citas</label><p class="formhint">Las citas existentes conservan precio, nombre y duración. Este cambio se aplica a nuevas reservas.</p>`,f=>{const data={name:f.get('name').trim(),price:Math.round(+f.get('price')*100)/100,duration:+f.get('duration'),prep:+f.get('prep'),active:f.has('active')};if(!data.name||!Number.isFinite(data.price)||data.price<0||!Number.isSafeInteger(data.duration)||data.duration<5||data.duration>480||!Number.isSafeInteger(data.prep)||data.prep<0||data.prep>60)throw Error('Revisa los valores del servicio.');if(s)Object.assign(s,data);else services.push(data);logAction('Catálogo actualizado: '+data.name);finish('Servicio guardado')})}
function teamPage(){$('#main').innerHTML=heading('Equipo y horarios','Organiza la jornada de cada profesional.','<button class="primary" onclick="staffForm()">＋ Agregar barbero</button>')+`<div class="cards">${barbers.map((b,i)=>`<article class="card"><span class="avatar">${esc(b.split(' ').map(x=>x[0]).join(''))}</span><h2 style="margin-top:18px">${esc(b)}</h2><p>${schedules[i].active?'Activo':'Inactivo'} · ${schedules[i].start}–${schedules[i].end}<br>Descanso: ${schedules[i].breakStart}–${schedules[i].breakEnd}<br>${schedules[i].days.map(d=>['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][d]).join(' · ')}</p><button onclick="staffForm(${i})">Editar horario</button></article>`).join('')}</div><div class="notice">Los profesionales de esta lista no tienen acceso de usuario. Esta entrega habilita únicamente la cuenta del propietario.</div>`}
function base_staffForm(id=null){if(role!=='Propietario')return;const s=schedules[id]||{start:'09:00',end:'18:00',breakStart:'13:00',breakEnd:'14:00',days:[1,2,3,4,5,6],active:true};modal(id===null?'Nuevo barbero':'Editar profesional',field('Nombre',input('name','text',barbers[id]||'','required maxlength="80"'))+`<div class="two">${field('Entrada',input('start','time',s.start,'required'))}${field('Salida',input('end','time',s.end,'required'))}${field('Descanso desde',input('bs','time',s.breakStart,'required'))}${field('Descanso hasta',input('be','time',s.breakEnd,'required'))}</div><div class="daychecks">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="d${d}" ${s.days.includes(d)?'checked':''}>${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][d]}</label>`).join('')}</div><label class="inlinecheck"><input type="checkbox" name="active" ${s.active?'checked':''}>Activo para nuevas citas</label><p class="formhint">No se permite dejar citas futuras fuera del horario. Reprográmalas primero.</p>`,f=>{const n=f.get('name').trim(),next={start:f.get('start'),end:f.get('end'),breakStart:f.get('bs'),breakEnd:f.get('be'),days:[0,1,2,3,4,5,6].filter(d=>f.has('d'+d)),active:f.has('active')};if(!n||next.start>=next.end||next.breakStart<next.start||next.breakEnd>next.end||next.breakStart>=next.breakEnd)throw Error('Revisa los horarios de jornada y descanso.');if(id!==null){const previous=schedules[id];schedules[id]=next;try{appointments.filter(a=>a.barber===id&&a.date>=today&&!['Completada','Cancelada','No asistió'].includes(a.status)).forEach(a=>validateBooking(a,a.id))}catch{ schedules[id]=previous;throw Error('Hay citas pendientes que quedarían fuera del horario. Reprográmalas antes.')}barbers[id]=n}else{barbers.push(n);schedules.push(next)}logAction('Horario actualizado: '+n);finish('Profesional guardado')})}
function reportDays(){if(!reportFrom||!reportTo||reportFrom>reportTo)return [];const out=[];let d=new Date(reportFrom+'T12:00:00');for(let n=0;d.toISOString().slice(0,10)<=reportTo&&n<366;n++){out.push(d.toISOString().slice(0,10));d.setDate(d.getDate()+1)}return out}
function download(filename,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function base_paymentForm(id){const a=appointments.find(a=>a.id===id);if(!cashOpen){notify('Abre la caja antes de registrar el cobro.');navigate('Caja');return}modal('Cobrar atención',`<h3>${esc(name(a))}</h3><p>Saldo: <b>${money(a.price-a.paid)}</b></p>`+field('Importe recibido (Bs)',input('amount','number',(a.price-a.paid).toFixed(2),'required min="0.01" step="0.01"'))+field('Método','<select name="method"><option>Efectivo</option><option>QR (registro manual)</option><option>Transferencia (registro manual)</option></select>')+'<p class="formhint">Puedes registrar un pago parcial. QR y transferencias requieren revisión manual.</p>',f=>{const amount=Math.round(+f.get('amount')*100)/100;if(!cashOpen||!Number.isFinite(amount)||amount<=0||amount>Math.round((a.price-a.paid)*100)/100)throw Error('El importe debe ser positivo y no superar el saldo.');a.paid=Math.round((a.paid+amount)*100)/100;movements.push({id:uuidNumber(),at:new Date().toISOString(),actor:role,date:localCashDate(),amount,type:f.get('method'),note:'Cobro · '+name(a),appointment:id,kind:a.status==='Completada'?'payment':'deposit',session:currentCashId});logAction('Pago de '+money(amount)+' · '+f.get('method'),id);finish('Pago registrado')})}
function legacy_cashAction(){if(!cashOpen){modal('Abrir una nueva caja',field('Fondo inicial en efectivo (Bs)',input('amount','number','0','required min="0" step="0.01"'))+'<p class="formhint">El fondo inicial no es un ingreso por ventas.</p>',f=>{opening=Math.round(+f.get('amount')*100)/100;if(!Number.isFinite(opening)||opening<0)throw Error('Revisa el importe.');currentCashId=uuidNumber();cashSessions.push({id:currentCashId,opening,date:today});cashOpen=true;closed=false;logAction('Apertura de caja: '+money(opening));finish('Caja abierta')})}else{const expected=cashExpected();modal('Cerrar caja',`<p>Efectivo esperado: <b>${money(expected)}</b></p>`+field('Efectivo contado (Bs)',input('amount','number',expected,'required min="0" step="0.01"'))+field('Motivo de diferencia',input('reason','text','','maxlength="180"')),f=>{const counted=Math.round(+f.get('amount')*100)/100;if(!Number.isFinite(counted)||counted<0)throw Error('Revisa el efectivo contado.');const diff=Math.round((counted-expected)*100)/100;if(diff&&!f.get('reason').trim())throw Error('Explica la diferencia de caja.');Object.assign(cashSessions.find(s=>s.id===currentCashId),{expected,counted,diff,reason:f.get('reason'),closed:true});cashOpen=false;closed=true;logAction('Caja cerrada · diferencia '+money(diff));finish('Cierre registrado: '+money(diff)+' de diferencia')})}}
function cashExpected(){return opening+movements.filter(m=>m.session===currentCashId&&m.type==='Efectivo').reduce((s,m)=>s+m.amount,0)}
function expenseForm(){if(!cashOpen)return notify('Abre la caja primero.');modal('Registrar gasto en efectivo',field('Concepto',input('note','text','','required maxlength="100"'))+field('Importe (Bs)',input('amount','number','','required min="0.01" step="0.01"')),f=>{const amount=Math.round(+f.get('amount')*100)/100;if(!Number.isFinite(amount)||amount<=0||!f.get('note').trim())throw Error('Revisa el importe y el concepto.');if(amount>cashExpected())throw Error('El gasto supera el efectivo disponible en esta caja.');movements.push({id:uuidNumber(),at:new Date().toISOString(),actor:role,date:localCashDate(),amount:-amount,type:'Efectivo',note:f.get('note').trim(),session:currentCashId});logAction('Gasto: '+money(amount));finish('Gasto registrado')})}
function base_cashPage(){const income=movements.filter(m=>m.amount>0).reduce((s,m)=>s+m.amount,0),pending=appointments.filter(a=>a.status==='Completada'&&a.paid<a.price);$('#main').innerHTML=heading('Caja y cobros','Cada movimiento queda separado de las citas y del fondo inicial.',`<button class="primary" onclick="cashAction()">${cashOpen?'Cerrar caja':'Abrir caja'}</button>`)+`<div class="stats">${stat('Caja actual',cashOpen?'Abierta':'Cerrada',cashOpen?'Lista para registrar movimientos':'Abre una caja para cobrar')}${stat('Cobrado',money(income),'Todos los medios de pago')}${stat('Efectivo de caja actual',cashOpen?money(cashExpected()):'—','Fondo + cobros − gastos')}${stat('Pendiente de cobrar',money(pending.reduce((s,a)=>s+a.price-a.paid,0)),'Atenciones finalizadas')}</div><div class="two"><section class="panel"><div class="panelhead"><h2>Atenciones por cobrar</h2></div>${pending.map(a=>`<div class="panelhead"><div><b>${esc(name(a))}</b><p class="muted">${money(a.price-a.paid)} · ${esc(a.serviceName)}</p></div><button onclick="paymentForm(${a.id})">Cobrar</button></div>`).join('')||'<div class="empty">No hay saldos pendientes</div>'}</section><section class="panel"><div class="panelhead"><h2>Movimientos</h2><button onclick="expenseForm()">＋ Gasto</button></div><div class="tablewrap"><table><tbody>${movements.slice().reverse().map(m=>`<tr><td>${esc(m.note)}<small>${esc(m.type)}${!m.session?' · registro inicial':''}</small></td><td>${money(m.amount)}</td></tr>`).join('')}</tbody></table></div></section></div><h2 class="subhead">Cierres de caja</h2><section class="panel"><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Esperado</th><th>Contado</th><th>Diferencia</th><th>Motivo</th></tr></thead><tbody>${cashSessions.filter(s=>s.closed).map(s=>`<tr><td>${s.date}</td><td>${money(s.expected)}</td><td>${money(s.counted)}</td><td>${money(s.diff)}</td><td>${esc(s.reason)||'Sin diferencia'}</td></tr>`).join('')||'<tr><td colspan="5">Aún no hay cierres en esta sesión.</td></tr>'}</tbody></table></div></section><p class="metrichelp">Los ingresos no son ganancias. No se emiten facturas fiscales.</p>`}
