function slotDetail(r,c){const x=heatData()[r][c];modal(weekdays[x.day]+' · '+clock(x.hour*60)+'–'+clock((x.hour+1)*60),`<div class="stats twostats">${stat('Ocupación',x.pct===null?'—':x.pct+'%',x.used+' / '+x.capacity+' minutos')}${stat('Atenciones',x.done,x.cites+' citas iniciadas en la franja')}</div><p>Canceladas: <b>${x.cancel}</b> · Ausencias: <b>${x.absent}</b></p><p>Cobrado asignado al tiempo de servicio: <b>${money(x.revenue)}</b></p><p class="formhint">El importe de servicios largos se distribuye proporcionalmente entre sus horas de atención. ${x.days} fechas con cobertura. ${reportFrom} a ${reportTo}.</p>${x.capacity&&heatMode==='attended'?`<button type="button" onclick="closeModal();promoForm(null,${x.day},'${clock(x.hour*60)}','${clock((x.hour+1)*60)}')">Crear promoción para esta franja</button>`:''}`,()=>closeModal())}
function promoPage(){$('#main').innerHTML=heading('Promociones','Los beneficios se calculan al reservar según la fecha y hora de atención.','<button class="primary" onclick="promoForm()">＋ Crear promoción</button>')+`<div class="cards">${promos.map(p=>{const uses=promoUses(p),done=appointments.filter(a=>a.promoId===p.id&&a.status==='Completada');return `<article class="card"><span class="badge ${!p.approved?'pending':''}">${promoState(p)}</span><h2 style="margin-top:16px">${esc(p.name)}</h2><strong class="price" style="font-size:1.3rem">${promoDescription(p)}</strong><p>${p.days.map(d=>weekdays[d]).join(', ')}<br>${p.start}–${p.end} · ${p.from} a ${p.to}<br>${p.cap} cupos ${p.capScope==='day'?'por día':'en total'} · ${p.clientLimit} por cliente</p><div class="summarystrip"><span>${uses.length} usos retenidos</span><span>${done.length} atenciones</span></div><div class="buttons" style="margin-top:17px">${!p.approved?`<button class="primary" onclick="approvePromo(${p.id})">Aprobar</button>`:`<button onclick="togglePromo(${p.id})">${p.paused?'Reanudar':'Pausar'}</button>`}<button onclick="promoForm(${p.id})">Editar</button><button onclick="promoResults(${p.id})">Resultados</button><button onclick="promoShare(${p.id})">Texto</button></div></article>`}).join('')}</div><div class="notice">Aprobar habilita el beneficio para citas elegibles; nunca envía mensajes. Los precios aceptados en citas existentes se conservan al pausar o editar. Una cita puede reservarse hoy para una promoción futura. Alcance: local principal.</div>`}
