 const observedEnd=p.to<historyEnd?p.to:historyEnd,observedDays=Math.max(0,Math.floor((new Date(observedEnd+'T12:00:00')-new Date(p.from+'T12:00:00'))/86400000)+1),weeks=Math.ceil(observedDays/7),priorFrom=shiftDate(p.from,-weeks*7),priorTo=shiftDate(observedEnd,-weeks*7);
