function stock(id){return stockLedger.filter(m=>m.product===id).reduce((s,m)=>s+m.delta,0)}
function inventoryPage(){$('#main').innerHTML=heading('Inventario','Distingue ventas de productos, entradas y consumo interno.','<button class="primary" onclick="productForm()">＋ Nuevo producto</button>')+`<div class="cards">${inventory.map(p=>`<article class="card"><span class="badge ${stock(p.id)<=p.min?'pending':''}">${stock(p.id)<=p.min?'Reponer':'Disponible'}</span><h2 style="margin-top:15px">${esc(p.name)}</h2><strong class="price">${stock(p.id)} <small style="font-size:1rem">unidades</small></strong><p>${money(p.price)} por unidad · mínimo ${p.min}</p><button onclick="stockForm(${p.id})">Registrar movimiento</button></article>`).join('')}</div><h2 class="subhead">Historial de movimientos</h2><section class="panel"><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Movimiento</th><th>Cantidad</th><th>Motivo</th></tr></thead><tbody>${stockLedger.slice().reverse().slice(0,30).map(m=>`<tr><td>${m.date}</td><td>${esc(inventory.find(p=>p.id===m.product).name)}</td><td>${m.kind}</td><td>${m.delta>0?'+':''}${m.delta}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div></section><p class="metrichelp">Las ventas generan un ingreso en la caja abierta. El consumo interno reduce existencias sin generar una venta. Los ajustes requieren motivo. No se calcula costo de ventas ni utilidad.</p>`}
function productForm(){modal('Nuevo producto',field('Nombre',input('name','text','','required maxlength="80"'))+field('Precio de venta (Bs)',input('price','number',0,'required min="0" step="0.01"'))+field('Mínimo de reposición',input('min','number',5,'required min="0" step="1"')),f=>{const price=round(+f.get('price')),min=+f.get('min');if(!f.get('name').trim()||price<0||!Number.isFinite(price)||!Number.isInteger(min)||min<0)throw Error('Revisa los datos.');inventory.push({id:uuidNumber(),name:f.get('name').trim(),price,min});finish('Producto creado con existencia cero')})}
function stockForm(id){const p=inventory.find(p=>p.id===id);modal('Movimiento · '+p.name,field('Tipo','<select name="kind"><option>Entrada</option><option>Venta</option><option>Consumo interno</option><option>Ajuste positivo</option><option>Ajuste negativo</option></select>')+field('Unidades',input('qty','number',1,'required min="1" step="1"'))+field('Motivo',input('reason','text','','required maxlength="150"'))+'<p class="formhint">La venta se registra en efectivo en la caja abierta.</p>',f=>{const qty=+f.get('qty'),kind=f.get('kind');if(kind==='Venta'){closeModal();sellProduct(id);return}const negative=['Venta','Consumo interno','Ajuste negativo'].includes(kind);if(!Number.isInteger(qty)||qty<=0||!f.get('reason').trim())throw Error('Cantidad entera positiva y motivo obligatorios.');if(negative&&qty>stock(id))throw Error('Existencia insuficiente.');if(kind==='Venta'&&!cashOpen)throw Error('Abre la caja antes de vender.');stockLedger.push({id:uuidNumber(),date:today,product:id,delta:negative?-qty:qty,kind,reason:f.get('reason')});if(kind==='Venta')movements.push({id:uuidNumber(),at:new Date().toISOString(),actor:role,date:localCashDate(),amount:round(qty*p.price),type:'Efectivo',note:'Venta · '+p.name+' × '+qty,kind:'sale',session:currentCashId});logAction(kind+': '+p.name+' × '+qty);finish('Movimiento de inventario registrado')})}
function earned(a){const rate=a.commissionSnapshot?.rate??40;return a.status==='Completada'?round(a.paid*rate/100):0}
function paidCommission(id){return settlements.flatMap(s=>s.items).filter(i=>i.appointment===id).reduce((n,i)=>n+i.amount,0)}
function legacy_commissionPage(){const rows=appointments.filter(a=>a.status==='Completada');$('#main').innerHTML=heading('Comisiones del equipo','Calculadas sobre el pago neto de servicios completados.')+`<div class="cards">${barbers.map((b,i)=>{const earnedTotal=round(rows.filter(a=>a.barber===i).reduce((s,a)=>s+earned(a),0)),paid=round(settlements.filter(s=>s.barber===i).reduce((n,s)=>n+s.total,0));return `<article class="card"><h2>${esc(b)}</h2><strong class="price">${money(earnedTotal-paid)}</strong><p>Saldo por liquidar · regla actual ${commissionRules[i]?.rate||40}%<br>Devengado: ${money(earnedTotal)}<br>Liquidado: ${money(paid)}</p><div class="buttons"><button onclick="commissionForm(${i})">Cambiar regla</button><button onclick="settleForm(${i})">Liquidar</button></div></article>`}).join('')}</div><div class="notice">Los descuentos reducen la base porque se usa el importe cobrado. Las devoluciones reducen la comisión; si ya se liquidó, generan un ajuste pendiente sin cambiar la liquidación anterior. Regla inicial: 40%, sin propinas ni montos fijos.</div><h2 class="subhead">Liquidaciones registradas</h2><section class="panel"><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Barbero</th><th>Importe</th><th>Servicios incluidos</th></tr></thead><tbody>${settlements.map(s=>`<tr><td>${s.date}</td><td>${esc(barbers[s.barber])}</td><td>${money(s.total)}</td><td>${s.items.length}</td></tr>`).join('')||'<tr><td colspan="4">Sin liquidaciones registradas</td></tr>'}</tbody></table></div></section>`}
function commissionForm(i){modal('Regla de comisión · '+barbers[i],field('Porcentaje para futuras atenciones',input('rate','number',commissionRules[i]?.rate??40,'required min="0" max="100" step="0.01"'))+'<p class="formhint">Los servicios ya completados conservan su regla. Esta edición se aplicará al completar nuevas atenciones.</p>',f=>{const rate=+f.get('rate');if(!Number.isFinite(rate)||rate<0||rate>100)throw Error('Usa un porcentaje entre 0 y 100.');commissionRules[i]={rate};logAction('Comisión futura: '+barbers[i]+' '+rate+'%');finish('Regla guardada')})}
function legacy_settleForm(i){const items=appointments.filter(a=>a.barber===i&&a.status==='Completada').map(a=>({appointment:a.id,amount:round(earned(a)-paidCommission(a.id))})).filter(x=>x.amount!==0),total=round(items.reduce((n,x)=>n+x.amount,0));if(total<=0)return notify('No hay un saldo positivo por liquidar. Los ajustes negativos se compensarán con futuras comisiones.');modal('Registrar liquidación',`<p>${esc(barbers[i])}<br><b>${money(total)}</b> · ${items.length} servicios y ajustes</p><p class="formhint">Registra el cálculo de la liquidación. No transfiere dinero ni descuenta efectivo de caja. El pago debe registrarse por separado.</p>`,()=>{settlements.push({id:uuidNumber(),date:today,barber:i,items,total});logAction('Comisión liquidada: '+barbers[i]+' '+money(total));finish('Liquidación registrada')})}
function blockForm(){modal('Bloquear agenda',field('Profesional',`<select name="barber">${barbers.map((b,i)=>`<option value="${i}">${esc(b)}</option>`).join('')}</select>`)+field('Fecha',input('date','date',day,'required'))+`<div class="two">${field('Desde',input('start','time','09:00','required'))}${field('Hasta',input('end','time','10:00','required'))}</div>`+field('Motivo',input('reason','text','','required maxlength="150"')),f=>{const b={id:uuidNumber(),barber:+f.get('barber'),date:f.get('date'),start:minutes(f.get('start')),end:minutes(f.get('end')),reason:f.get('reason').trim()};if(b.date<today||b.start>=b.end||!b.reason)throw Error('Revisa fecha, horario y motivo.');if(appointments.some(a=>a.barber===b.barber&&a.date===b.date&&!['Cancelada','No asistió'].includes(a.status)&&minutes(a.time)<b.end&&minutes(a.time)+a.duration+(a.prep||0)>b.start))throw Error('El bloqueo se cruza con una cita. Reprográmala primero.');blocks.push(b);logAction('Agenda bloqueada: '+b.reason);finish('Bloqueo registrado')})}
function removeBlock(id){const b=blocks.find(x=>x.id===id);modal('Eliminar bloqueo',`<p>${esc(b.reason)} · ${b.date} ${clock(b.start)}–${clock(b.end)}</p>`,()=>{blocks=blocks.filter(x=>x.id!==id);logAction('Bloqueo eliminado');finish('Horario liberado')})}
