function agendaScope(){const start=calendarMode==='week'?shiftDate(day,-((dayOf(day)+6)%7)):day,end=calendarMode==='week'?shiftDate(start,6):day;return appointments.filter(a=>a.date>=start&&a.date<=end&&(role!=='Barbero'||a.barber===0)&&(filter==='Todos'||a.barber===+filter))}
function depositFields(old){if(role==='Barbero')return '';return `<fieldset class="depositbox"><legend>Anticipo de reserva</legend><p>Ya abonado: <b>${money(old?.paid||0)}</b>. Registra solo el dinero nuevo recibido.</p>${field('Anticipo recibido ahora (Bs)',input('deposit','number',0,'min="0" step="0.01"'))}${field('Medio de pago','<select name="depositMethod"><option>Efectivo</option><option>QR (registro manual)</option><option>Transferencia (registro manual)</option></select>')}<p class="formhint">Si no dejó anticipo, conserva 0. Para recibir dinero, abre primero la caja. QR y transferencia requieren revisión manual.</p></fieldset>`}
function validateDeposit(f,a){const raw=f.get('deposit'),amount=raw===null?0:Number(raw);if(!Number.isFinite(amount)||amount<0||Math.abs(amount*100-Math.round(amount*100))>0.00001)throw Error('Escribe un anticipo válido con hasta dos decimales.');if(amount===0)return 0;if(role==='Barbero')throw Error('Este perfil no registra cobros.');if(!cashOpen)throw Error('Abre la caja antes de registrar el anticipo. Puedes guardar la cita con anticipo 0.');if(amount>round(a.price-a.paid))throw Error('El anticipo no puede superar el saldo.');if(!['Efectivo','QR (registro manual)','Transferencia (registro manual)'].includes(f.get('depositMethod')))throw Error('Selecciona el medio de pago.');return amount}
function recordDeposit(a,amount,method){a.paid=round(a.paid+amount);movements.push({id:uuidNumber(),at:new Date().toISOString(),actor:role,date:localCashDate(),amount,type:method,note:'Anticipo de reserva · '+name(a),appointment:a.id,kind:'deposit',session:currentCashId});logAction('Anticipo '+money(amount)+' · '+method,a.id)}
function paymentSummary(a){if(role==='Barbero')return '';const deposits=movements.filter(m=>m.appointment===a.id&&m.kind==='deposit');return `<div class="payment-summary"><span>Total <b>${money(a.price)}</b></span><span>Anticipo <b>${money(deposits.reduce((n,m)=>n+m.amount,0))}</b></span>${deposits.length?`<small>${[...new Set(deposits.map(m=>m.type))].map(esc).join(' · ')}</small>`:''}<span>Abonado neto <b>${money(a.paid)}</b></span><span class="balance">Saldo <b>${money(round(a.price-a.paid))}</b></span></div>`}
function paymentHistory(a){if(role==='Barbero')return '';return movements.filter(m=>m.appointment===a.id).map(m=>`<p>${esc(m.date)} · ${m.amount<0?'Devolución':m.kind==='deposit'?'Anticipo':'Pago'} · ${esc(m.type)} · <b>${money(m.amount)}</b></p>`).join('')||'<p class="muted">Sin pagos registrados.</p>'}
function reminderDue(a,now=Date.now()){if(!['Pendiente','Confirmada'].includes(a.status))return false;const delta=new Date(a.date+'T'+a.time+':00-04:00').getTime()-now;return delta>=0&&delta<=3600000}
function reminderCard(a){const left=Math.max(0,Math.ceil((new Date(a.date+'T'+a.time+':00-04:00').getTime()-Date.now())/60000));return `<div class="reminder"><b>Recordatorio · en ${left} min</b><button type="button" onclick="whatsapp(${a.id})">Recordar por WhatsApp</button><small>El mensaje se envía desde WhatsApp.</small></div>`}
function reminderBanner(){const due=agendaScope().filter(a=>reminderDue(a));return due.length?`<div class="reminder-banner" role="status">${due.length} ${due.length===1?'cita empieza':'citas empiezan'} en la próxima hora. Revisa las tarjetas resaltadas para preparar el recordatorio.</div>`:''}
if(typeof setInterval==='function'){setInterval(()=>{if(view==='Agenda'&&!$('#modal').open){const focused=document.activeElement;if(focused?.closest?.('input,select,textarea'))return;agenda()}},30000);window.addEventListener('focus',()=>{if(view==='Agenda'&&!$('#modal').open)agenda()})}

function freeRanges(date,barber,now=Date.now()){if(!schedules[barber]?.active)return [];let free=ranges(date,barber);for(const a of appointments.filter(a=>a.date===date&&a.barber===barber&&!['Cancelada','No asistió'].includes(a.status))){const start=minutes(a.time),end=start+a.duration+(a.prep||0);free=free.flatMap(([x,y])=>[[x,Math.min(y,start)],[Math.max(x,end),y]].filter(([l,r])=>r>l))}const midnight=Date.parse(date+'T00:00:00-04:00'),cutoff=Math.max(0,Math.ceil((now-midnight)/60000/5)*5);return free.map(([x,y])=>[Math.max(x,cutoff),y]).filter(([x,y])=>y>x)}
function availableStarts(date,barber,service,now=Date.now()){const s=services[service];if(!s?.active)return [];const duration=s.duration+(s.prep||0);return freeRanges(date,barber,now).flatMap(([x,y])=>{const starts=[];for(let n=Math.ceil(x/5)*5;n+duration<=y;n+=5)starts.push(n);return starts})}
function availabilityPanel(){if(!services[availabilityService]?.active)availabilityService=services.findIndex(s=>s.active);const service=services[availabilityService],start=calendarMode==='week'?shiftDate(day,-((dayOf(day)+6)%7)):day;const dates=Array.from({length:calendarMode==='week'?7:1},(_,i)=>shiftDate(start,i));const staff=activeStaff().filter(b=>(role!=='Barbero'||b.id===0)&&(filter==='Todos'||b.id===+filter));return `<section class="panel availability-panel"><div class="panelhead"><div><h2>Espacios disponibles</h2><p class="muted">Elige servicio y profesional; abre una franja para reservar.</p></div><label>Servicio<select aria-label="Servicio para disponibilidad" onchange="availabilityService=+this.value;render()">${services.map((s,i)=>s.active?`<option value="${i}" ${i===availabilityService?'selected':''}>${esc(s.name)} · ${s.duration+(s.prep||0)} min</option>`:'').join('')}</select></label></div><div class="availability-grid ${calendarMode==='week'?'availability-week':''}">${dates.map(date=>`<div class="availability-day"><h3>${new Date(date+'T12:00:00-04:00').toLocaleDateString('es-BO',{weekday:'short',day:'numeric',month:'short',timeZone:'America/La_Paz'})}</h3>${staff.map(b=>{const free=freeRanges(date,b.id).filter(([x,y])=>service&&y-x>=service.duration+(service.prep||0));return `<div class="availability-staff"><b>${esc(b.name)}</b>${free.length?free.map(([x,y])=>`<details><summary>${timeLabel(clock(x))}–${timeLabel(clock(y))}</summary><div class="slot-buttons">${availableStarts(date,b.id,availabilityService).filter(n=>n>=x&&n<y).map(n=>`<button onclick="bookFreeSlot('${date}',${b.id},${availabilityService},'${clock(n)}')">${timeLabel(clock(n))}</button>`).join('')}</div></details>`).join(''):'<small>Sin espacio para este servicio</small>'}</div>`}).join('')||'<p>No hay profesionales activos.</p>'}</div>`).join('')}</div><p class="metrichelp" style="padding:0 20px 16px">Horarios de Bolivia. Se descuentan citas, preparación, descansos y bloqueos. Solo se muestran espacios futuros donde cabe el servicio completo. El filtro de estado no libera horarios ocupados.</p></section>`}
function bookFreeSlot(date,barber,service,time){if(!availableStarts(date,barber,service).includes(minutes(time))){render();return notify('Este horario ya no está disponible. Elige otro.')}bookingForm(null,date,{barber,service,time})}

function localCashDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/La_Paz',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function stamp(at){return at?new Date(at).toLocaleString('es-BO',{timeZone:'America/La_Paz',hour12:true}):'Hora no registrada'}
function countCash(f){const counts=['bills','coins'].map((key,i)=>{const amount=Number(f.get(key)||0);if(!Number.isFinite(amount)||amount<0||amount>100000000||Math.abs(amount*100-Math.round(amount*100))>0.00001)throw Error('Ingresa importes no negativos con hasta dos decimales.');return {label:i?'Monedas':'Billetes',amount:round(amount)}});return {counts,total:round(counts.reduce((n,x)=>n+Math.round(x.amount*100),0)/100)}}
function countFields(){return `<h3>Efectivo disponible</h3><div class="two">${field('Importe en billetes (Bs)',input('bills','number',0,'required min="0" max="100000000" step="0.01" inputmode="decimal"'))}${field('Importe en monedas (Bs)',input('coins','number',0,'required min="0" max="100000000" step="0.01" inputmode="decimal"'))}</div><p class="formhint">Escribe cuánto dinero hay en billetes y cuánto en monedas. El total se calcula automáticamente.</p><div class="quote" id="cashCountPreview" aria-live="polite"></div>`}
function sessionMoves(id){return movements.filter(m=>m.session===id)}
function methodNet(id,type){return round(sessionMoves(id).filter(m=>m.type===type).reduce((n,m)=>n+m.amount,0))}
function differenceLabel(diff){return diff===0?'Cuadra':diff<0?'Faltante de '+money(-diff):'Sobrante de '+money(diff)}
function cashAction(){if(role==='Barbero')return notify('Perfil sin acceso a caja.');const closing=cashOpen,id=currentCashId;modal(closing?'Arqueo y cierre de caja':'Apertura de caja',countFields()+(closing?'<div id="digitalCloseSummary"></div>':'')+field('Observaciones / motivo de diferencia',input('reason','text','','maxlength="300"'))+'<p class="formhint">El QR se suma desde los cobros registrados, sin volver a ingresarlo al cerrar. No verifica el banco. El fondo inicial no es una venta.</p>',f=>{if(closing!==cashOpen||(closing&&id!==currentCashId))throw Error('La caja cambió. Vuelve a abrir el formulario.');const count=countCash(f),at=new Date().toISOString(),reason=String(f.get('reason')||'').trim();if(!closing){opening=count.total;currentCashId=uuidNumber();cashSessions.push({id:currentCashId,date:localCashDate(),opening,openingCounts:count.counts,openedAt:at,openedBy:role,openingNote:reason,closed:false});cashOpen=true;closed=false;cashViewId='current';logAction('Apertura de caja '+money(opening));finish('Caja abierta')}else{const expected=round(cashExpected()),diff=round(count.total-expected);const digital=['QR (registro manual)','Transferencia (registro manual)'].map(type=>({type,expected:methodNet(id,type),reviewed:null,diff:null,source:'movimientos'}));if(diff&&!reason)throw Error('Explica la diferencia del efectivo contado.');Object.assign(cashSessions.find(x=>x.id===id),{expected,counted:count.total,closingCounts:count.counts,diff,reason,closed:true,closedAt:at,closedBy:role,digital,qrNet:methodNet(id,'QR (registro manual)'),closingTotal:round(count.total+digital.reduce((n,d)=>n+d.expected,0)),movementSnapshot:structuredClone(sessionMoves(id))});cashOpen=false;closed=true;cashViewId=String(id);logAction('Cierre de caja · '+differenceLabel(diff));finish(differenceLabel(diff))}});const update=()=>{try{const c=countCash(new FormData($('#form')));if(closing)$('#digitalCloseSummary').innerHTML=qrCloseSummary(id,c.total);$('#cashCountPreview').innerHTML=`<span>Efectivo contado</span><strong>${money(c.total)}</strong>${closing?`<small>Esperado: ${money(cashExpected())} · ${differenceLabel(round(c.total-cashExpected()))}</small>`:'<small>Este será el fondo inicial de la caja.</small>'}`}catch(e){$('#cashCountPreview').textContent=e.message}};$('#fields').oninput=update;update()}
function cashLedger(rows){return `<div class="tablewrap"><table><thead><tr><th>Fecha y hora</th><th>Concepto / referencia</th><th>Medio</th><th>Entrada</th><th>Salida</th><th>Perfil</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${m.at?stamp(m.at):esc(m.date)+' · hora no registrada'}</td><td>${esc(m.note)}<small>Movimiento ${m.id}${m.appointment?' · Cita '+m.appointment:''}</small></td><td>${esc(m.type)}</td><td>${m.amount>0?money(m.amount):'—'}</td><td>${m.amount<0?money(-m.amount):'—'}</td><td>${esc(m.actor||'No registrado')}</td></tr>`).join('')||'<tr><td colspan="6">Sin movimientos para esta selección.</td></tr>'}</tbody></table></div>`}
function cashPage(){const selected=cashViewId==='current'?cashSessions.find(s=>s.id===currentCashId):cashSessions.find(s=>String(s.id)===cashViewId),rows=selected?(selected.movementSnapshot||sessionMoves(selected.id)):[],pending=appointments.filter(a=>a.status==='Completada'&&a.paid<a.price);$('#main').innerHTML=heading('Caja y arqueos','Control de efectivo, pagos digitales y movimientos por apertura.',`<button class="primary" onclick="cashAction()">${cashOpen?'Arqueo y cierre':'Abrir caja'}</button>`)+`<div class="stats">${stat('Caja actual',cashOpen?'Abierta':'Cerrada',cashOpen?stamp(cashSessions.find(s=>s.id===currentCashId)?.openedAt):'Selecciona un cierre para consultar')}${stat('Efectivo esperado',cashOpen?money(cashExpected()):'—','Fondo + entradas en efectivo − salidas')}${stat('QR neto actual',cashOpen?money(methodNet(currentCashId,'QR (registro manual)')):'—','Registro manual, separado del efectivo')}${stat('Total esperado de caja',cashOpen?money(cashExpected()+methodNet(currentCashId,'QR (registro manual)')+methodNet(currentCashId,'Transferencia (registro manual)')):'—','Fondo + efectivo neto + pagos digitales')}</div><section class="panel"><div class="panelhead"><h2>Historial completo de movimientos</h2><div class="filters"><select aria-label="Caja consultada" onchange="cashViewId=this.value;cashPage()"><option value="current">Caja actual / última apertura</option>${cashSessions.slice().reverse().map(x=>`<option value="${x.id}" ${cashViewId===String(x.id)?'selected':''}>${x.date} · ${x.id} · ${x.closed?'Cerrada':'Abierta'}</option>`).join('')}</select><select aria-label="Medio de pago" onchange="cashMethod=this.value;cashPage()">${['Todos','Efectivo','QR (registro manual)','Transferencia (registro manual)'].map(x=>`<option ${cashMethod===x?'selected':''}>${x}</option>`).join('')}</select><button onclick="expenseForm()">Registrar gasto</button>${selected?`<button onclick="cashReport(${selected.id})">Descargar arqueo</button>`:''}</div></div>${selected?`<div style="padding:18px"><b>Apertura: ${money(selected.opening)}</b> · ${stamp(selected.openedAt)} · ${esc(selected.openedBy||'Perfil no registrado')}${selected.closed?`<p>Cierre: ${stamp(selected.closedAt)} · ${esc(selected.closedBy||'Perfil no registrado')}<br>Esperado ${money(selected.expected)} · Contado ${money(selected.counted)} · <b>${differenceLabel(selected.diff)}</b><br>Motivo: ${esc(selected.reason||'Sin diferencia')}</p>`:''}<p>${['Efectivo','QR (registro manual)','Transferencia (registro manual)'].map(type=>esc(type)+': '+money(rows.filter(m=>m.type===type).reduce((n,m)=>n+m.amount,0))).join(' · ')}</p>${(selected.digital||[]).map(d=>`<p>${esc(d.type)}: registrado ${money(d.expected)} · ${d.reviewed===null?'Sumado automáticamente desde movimientos; sin verificación bancaria':'revisado '+money(d.reviewed)+' · '+differenceLabel(d.diff)}</p>`).join('')}<details><summary>Ver conteo de apertura y cierre</summary>${denomSummary(selected.openingCounts,'Apertura')}${denomSummary(selected.closingCounts,'Cierre')}</details></div>`:'<p style="padding:20px">Abre una caja o selecciona una del historial.</p>'}${cashLedger(rows.filter(m=>cashMethod==='Todos'||m.type===cashMethod).slice().reverse())}</section><h2 class="subhead">Atenciones pendientes de cobro</h2><section class="panel">${pending.map(a=>`<div class="panelhead"><span>${esc(name(a))} · ${esc(a.date)} · ${money(a.price-a.paid)}</span><button onclick="paymentForm(${a.id})">Cobrar</button></div>`).join('')||'<p style="padding:20px">Sin saldos pendientes.</p>'}</section><p class="metrichelp">Cada apertura, cierre y movimiento conserva su registro. Los cobros QR se suman desde los movimientos y requieren revisión bancaria manual.</p>`}
function denomSummary(counts,title){return `<p><b>${title}</b><br>${counts?counts.map(x=>x.amount!==undefined?esc(x.label)+': '+money(x.amount):money(x.value)+' × '+x.qty+' = '+money(x.value*x.qty)).join('<br>'):'Conteo no registrado'}</p>`}
function legacy_cashReport(id){const s=cashSessions.find(x=>x.id===id);if(!s)return;download('arqueo-'+id+'.json',JSON.stringify({tipo:'Arqueo interno',timezone:'America/La_Paz',caja:s,movimientos:s.movementSnapshot||sessionMoves(id),nota:'Registro de sesión. No constituye verificación bancaria ni respaldo con restauración.'},null,2),'application/json');notify('Arqueo y movimientos descargados')}

function paymentForm(id){if(role==='Barbero')return notify('Este perfil no registra cobros.');const a=appointments.find(x=>x.id===id);if(!a||['Cancelada','No asistió'].includes(a.status))return notify('Esta cita no admite cobros.');if(!cashOpen)return notify('Abre la caja antes de cobrar.');modal('Cobrar servicio',`<h3>${esc(name(a))}</h3>${paymentSummary(a)}`+field('Importe recibido ahora (Bs)',input('amount','number',round(a.price-a.paid),'required min="0" step="0.01"'))+field('Medio de pago',paymentMethods())+(a.status!=='Completada'?'<label class="inlinecheck"><input name="complete" type="checkbox">El servicio ya terminó</label>':'')+'<p class="formhint">El anticipo ya está descontado del saldo. Marca que terminó solo si el cliente fue atendido; cobrar por adelantado no completa la cita. QR y transferencia se registran manualmente.</p>',f=>{const amount=Number(f.get('amount')),method=f.get('method'),complete=f.has('complete')&&a.status!=='Completada';if(!cashOpen)throw Error('La caja está cerrada.');if(!Number.isFinite(amount)||amount<0||amount>round(a.price-a.paid)||Math.abs(amount*100-Math.round(amount*100))>0.00001)throw Error('Revisa el importe: no puede superar el saldo.');if(amount===0&&!complete)throw Error('Ingresa un pago o confirma que el servicio terminó.');if(!['Efectivo','QR (registro manual)','Transferencia (registro manual)'].includes(method))throw Error('Selecciona el medio de pago.');if(complete){a.status='Completada';a.commissionSnapshot=a.commissionSnapshot||{rate:commissionRules[a.barber]?.rate||0,base:'cobrado neto de devoluciones'};logAction('Servicio finalizado desde cobro',id)}if(amount>0){a.paid=round(a.paid+amount);movements.push({id:uuidNumber(),at:new Date().toISOString(),actor:role,date:localCashDate(),amount,type:method,note:(a.status==='Completada'?'Cobro':'Anticipo')+' · '+name(a),appointment:id,kind:a.status==='Completada'?'payment':'deposit',session:currentCashId});logAction('Pago '+money(amount)+' · '+method,id)}finish('Registro guardado · saldo '+money(a.price-a.paid))})}
function paymentMethods(){return '<select name="method"><option>Efectivo</option><option>QR (registro manual)</option><option>Transferencia (registro manual)</option></select>'}
function productSalesPage(){if(role==='Barbero')return;$('#main').innerHTML=heading('Venta de productos','Selecciona un producto para registrar su venta y cobro.')+`<div class="cards">${inventory.map(p=>`<article class="card"><h2>${esc(p.name)}</h2><strong class="price">${money(p.price)}</strong><p>Disponible: ${stock(p.id)} unidades</p><button class="primary" ${stock(p.id)<=0?'disabled':''} onclick="sellProduct(${p.id})">Vender producto</button></article>`).join('')||'<p>No hay productos. Agrégalos desde Inventario.</p>'}</div><h2 class="subhead">Ventas registradas</h2><section class="panel">${cashLedger(movements.filter(m=>m.kind==='sale').slice().reverse())}</section>`}
function sellProduct(id){if(role==='Barbero')return notify('Perfil sin acceso a ventas.');if(!cashOpen)return notify('Abre la caja antes de vender.');const p=inventory.find(x=>x.id===id);if(!p)return;modal('Vender · '+p.name,`<p>Precio unitario: <b>${money(p.price)}</b> · disponibles ${stock(id)}</p>`+field('Barbero que recibe la comisión',`<select name="saleBarber" required><option value="">Selecciona un barbero</option>${activeStaff().map(b=>`<option value="${b.id}">${esc(b.name)} · ${productRates[b.id]===undefined?'Comisión sin configurar':productRates[b.id]+'%'}</option>`).join('')}</select>`)+field('Cantidad',input('qty','number',1,'required min="1" step="1"'))+field('Medio de pago',paymentMethods())+'<div class="quote" id="saleTotal"></div><p class="formhint">Se cobra el total y se descuenta del inventario al guardar. QR y transferencia requieren revisión manual.</p>',f=>{const qty=Number(f.get('qty')),method=f.get('method');if(!cashOpen)throw Error('La caja está cerrada.');if(!Number.isSafeInteger(qty)||qty<=0||qty>stock(id))throw Error('Revisa la cantidad y la existencia disponible.');if(!['Efectivo','QR (registro manual)','Transferencia (registro manual)'].includes(method))throw Error('Selecciona el medio de pago.');const raw=f.get('saleBarber'),barber=Number(raw);if(raw==null||raw===''||!schedules[barber]?.active)throw Error('Selecciona el barbero que recibe la comisión.');if(productRates[barber]===undefined)throw Error('El propietario debe configurar la comisión de productos en Comisiones.');const rate=productRates[barber];const saleId=uuidNumber(),amount=round(qty*p.price),at=new Date().toISOString();stockLedger.push({id:uuidNumber(),product:id,delta:-qty,kind:'Venta',reason:'Venta '+saleId,date:localCashDate(),saleId});movements.push({id:saleId,at,actor:role,date:localCashDate(),amount,type:method,note:'Venta · '+p.name+' × '+qty+' · Comisión para '+barbers[barber],kind:'sale',product:id,quantity:qty,unitPrice:p.price,barber,commissionRate:rate,commissionAmount:round(amount*rate/100),session:currentCashId});logAction('Venta '+p.name+' × '+qty+' · '+money(amount));finish('Venta registrada: '+money(amount))});const refresh=()=>{const qty=Number($('#form [name=qty]')?.value||1);$('#saleTotal').textContent='Total a cobrar: '+money(round(qty*p.price))};$('#fields').oninput=refresh;refresh()}

function reportTable(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(v=>`<td>${esc(String(v??'—'))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Sin registros.</td></tr>`}</tbody></table>`}
function reportFacts(items){return `<div class="facts">${items.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(String(value))}</strong></div>`).join('')}</div>`}
function reportDocument(title,subtitle,body){return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} · The Barber Haircuts & Shaves</title><style>*{box-sizing:border-box}body{margin:0;background:#edf1f5;color:#1c2c39;font:14px/1.55 Arial,sans-serif}.paper{max-width:1100px;margin:30px auto;padding:42px;background:white;border-radius:12px;box-shadow:0 8px 35px #172d4014}header{border-bottom:3px solid #b68a46;padding-bottom:22px;margin-bottom:26px}.brand{font-size:15px;letter-spacing:3px;font-weight:bold;color:#725429}h1{font-size:29px;line-height:1.2;margin:18px 0 8px}h2{font-size:18px;margin:30px 0 12px}p{margin:8px 0}.muted,header p{color:#617383}.toolbar{max-width:1100px;margin:20px auto;padding:0 12px;display:flex;align-items:center;gap:15px}.toolbar button{border:0;background:#183c53;color:white;border-radius:7px;padding:13px 20px;cursor:pointer;font-weight:bold}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.facts>div{background:#f3f6f8;border:1px solid #e1e7ed;border-radius:8px;padding:14px}.facts span{display:block;font-size:12px;color:#5e7282}.facts strong{display:block;margin-top:4px;font-size:17px;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin:12px 0 24px;font-size:12px;table-layout:fixed}th{background:#183c53;color:white;text-align:left;padding:10px}td{padding:9px;border-bottom:1px solid #e0e6eb;vertical-align:top;overflow-wrap:anywhere}tr:nth-child(even) td{background:#f7f9fb}.note{background:#fff7e7;border-left:3px solid #bb934c;padding:13px;margin:20px 0}.result{font-size:20px;font-weight:bold;padding:16px;background:#edf4f8;border-radius:8px}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:45px;margin:50px 0 20px}.signatures div{border-top:1px solid #9eabb6;padding-top:8px}footer{border-top:1px solid #dce3e8;padding-top:15px;margin-top:32px;color:#637583;font-size:11px}@media(max-width:650px){.paper{margin:10px;padding:18px}.facts{grid-template-columns:1fr 1fr}table{font-size:10px}td,th{padding:6px}.toolbar{flex-wrap:wrap}}@page{size:A4;margin:14mm}@media print{body{background:white;font-size:11px}.paper{max-width:none;margin:0;padding:0;box-shadow:none;border-radius:0}.toolbar{display:none}h1{font-size:24px}thead{display:table-header-group}tr,.facts>div,.signatures{break-inside:avoid}h2{break-after:avoid}th{color:#172f43;background:#e4ecf2}table{font-size:10px}footer{font-size:9px}}</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir / Guardar como PDF</button><span>Abre este documento en tu navegador. Para PDF, selecciona «Guardar como PDF» al imprimir.</span></div><main class="paper"><header><div class="brand">THE BARBER HAIRCUTS & SHAVES</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p><p>The Barber Haircuts & Shaves · Importes en bolivianos (Bs)</p></header>${body}<footer>Emitido: ${esc(stamp(new Date().toISOString()))} · Hora de Bolivia<br>Documento interno. No es factura fiscal. No acredita verificación bancaria ni reemplaza un respaldo del sistema.</footer></main></body></html>`}
function saveReport(filename,title,subtitle,body){download(filename+'.html',reportDocument(title,subtitle,body),'text/html;charset=utf-8');notify('Informe descargado. Ábrelo en el navegador para leer, imprimir o guardar como PDF.')}
function movementReport(rows){return reportTable(['Fecha y hora','Concepto','Medio','Entrada (Bs)','Salida (Bs)','Perfil'],rows.map(m=>[m.at?stamp(m.at):m.date+' · hora no registrada',m.note+' · Ref. '+m.id,m.type,m.amount>0?money(m.amount):'—',m.amount<0?money(-m.amount):'—',m.actor||'No registrado']))}
function countsReport(counts){return counts?reportTable(['Tipo de efectivo','Importe'],counts.map(x=>x.amount!==undefined?[x.label,money(x.amount)]:[money(x.value)+' × '+x.qty,money(x.value*x.qty)])):'<p class="muted">Desglose no registrado.</p>'}
function cashReport(id){const s=cashSessions.find(x=>x.id===id);if(!s||role==='Barbero')return;const rows=s.movementSnapshot||sessionMoves(id),methods=['Efectivo','QR (registro manual)','Transferencia (registro manual)'];const net=type=>round(rows.filter(m=>m.type===type).reduce((n,m)=>n+m.amount,0)),expected=round(s.opening+net('Efectivo')),digital=round(net(methods[1])+net(methods[2]));saveReport('arqueo-'+id,s.closed?'Arqueo y cierre de caja':'Estado de caja abierta','Caja '+id+' · '+(s.closed?'Cierre registrado':'Informe provisional: aún no se cerró'),reportFacts([['Apertura',stamp(s.openedAt)],['Cierre',s.closed?stamp(s.closedAt):'Caja abierta'],['Fondo inicial',money(s.opening)],['Efectivo esperado',money(s.closed?s.expected:expected)],['Efectivo contado',s.closed?money(s.counted):'Pendiente de arqueo'],['Diferencia en efectivo',s.closed?differenceLabel(s.diff):'Sin cierre']])+`<p>Apertura registrada por: <b>${esc(s.openedBy||'No registrado')}</b> · Cierre: <b>${esc(s.closedBy||'Pendiente / no registrado')}</b></p><h2>Resumen por medio de pago</h2>`+reportTable(['Medio','Entradas','Salidas','Neto'],methods.map(type=>{const list=rows.filter(m=>m.type===type);return [type,money(list.filter(m=>m.amount>0).reduce((n,m)=>n+m.amount,0)),money(-list.filter(m=>m.amount<0).reduce((n,m)=>n+m.amount,0)),money(net(type))]}))+reportFacts([['Total neto de movimientos',money(rows.reduce((n,m)=>n+m.amount,0))],['Fondo + efectivo neto + digitales',money(expected+digital)],['Efectivo contado + digitales registrados',s.closed?money(s.counted+digital):'Pendiente de cierre']])+`<div class="note">El fondo inicial no es una venta. Efectivo esperado = fondo inicial + entradas en efectivo − salidas en efectivo. Los totales digitales son registros manuales; sumarlos al efectivo no verifica que hayan llegado al banco.</div><h2>Pagos digitales calculados desde los movimientos</h2>`+reportTable(['Medio','Registrado','Revisado manualmente','Resultado'],(s.digital||methods.slice(1).map(type=>({type,expected:net(type),reviewed:null}))).map(d=>[d.type,money(d.expected),d.reviewed===null?'Sin revisar':money(d.reviewed),d.reviewed===null?'Pendiente':differenceLabel(d.diff)]))+`<h2>Efectivo de apertura</h2>`+countsReport(s.openingCounts)+`<h2>Efectivo de cierre</h2>`+countsReport(s.closingCounts)+`<h2>Observaciones</h2><p>Apertura: ${esc(s.openingNote||'Sin observaciones')}</p><p>Cierre: ${esc(s.reason||'Sin observaciones registradas')}</p><h2>Detalle de todos los movimientos (${rows.length})</h2>`+movementReport(rows)+`<div class="signatures"><div>Responsable de caja · firma</div><div>Revisado por · firma</div></div>`)}
function receipt(id){const a=appointments.find(x=>x.id===id);if(!a||role==='Barbero')return;saveReport('comprobante-'+id,'Comprobante interno','Cita '+id+' · No es factura fiscal',reportFacts([['Cliente',name(a)],['Profesional',barbers[a.barber]],['Atención',displayDate(a.date)+' · '+timeLabel(a.time)],['Total del servicio',money(a.price)],['Abonado neto',money(a.paid)],['Saldo pendiente',money(a.price-a.paid)]])+`<h2>Servicio</h2><p>${esc(a.serviceName)}</p><p>Estado de atención: ${esc(a.status)}</p><h2>Pagos y devoluciones</h2>`+movementReport(movements.filter(m=>m.appointment===id)))}
function appointmentReport(rows){return reportTable(['Fecha / hora','Cliente','Profesional / servicio','Estado','Total','Abonado','Saldo'],rows.map(a=>[displayDate(a.date)+' '+timeLabel(a.time),name(a),barbers[a.barber]+' / '+a.serviceName,a.status,money(a.price),money(a.paid),money(a.price-a.paid)]))}
function statsReport(){if(role==='Barbero')return;const m=metrics(reportFrom,reportTo);saveReport('estadisticas-'+reportFrom+'-'+reportTo,'Informe de actividad',displayDate(reportFrom)+' al '+displayDate(reportTo)+' · Profesional: '+(filter==='Todos'?'Todo el equipo':barbers[+filter])+' · Servicio: '+(serviceFilter==='Todos'?'Todos':services[+serviceFilter]?.name||serviceFilter),reportFacts([['Cobrado neto de servicios',money(m.income)],['Atenciones completadas',m.done.length],['Clientes atendidos',m.clients],['Cancelaciones',m.cancel],['Ausencias',m.absent],['Descuentos en atenciones',money(m.discount)]])+`<div class="note">Cobrado neto por fecha del movimiento, descontando devoluciones. No incluye fondo inicial ni ventas de productos. Los ingresos no equivalen a ganancias.</div><h2>Citas del período</h2>`+appointmentReport(m.rows))}
function exportDemo(){if(role!=='Propietario')return;saveReport('registros-barbe-shop','Registro general de operaciones','Registros de la barbería',reportFacts([['Clientes',clients.length],['Citas',appointments.length],['Movimientos',movements.length]])+`<h2>Citas</h2>`+appointmentReport(appointments)+`<h2>Movimientos de caja</h2>`+movementReport(movements)+`<h2>Clientes</h2>`+reportTable(['Nombre','Teléfono','Notas'],clients.map(c=>[c.name,c.phone||'No registrado',c.notes||'—']))+`<h2>Inventario actual</h2>`+reportTable(['Producto','Precio unitario','Existencias'],inventory.map(p=>[p.name,money(p.price),stock(p.id)]))+`<h2>Aperturas y cierres</h2>`+reportTable(['Caja','Apertura','Fondo','Cierre','Contado','Diferencia'],cashSessions.map(s=>[s.id,stamp(s.openedAt),money(s.opening),s.closed?stamp(s.closedAt):'Abierta',s.closed?money(s.counted):'—',s.closed?differenceLabel(s.diff):'—']))+`<h2>Promociones</h2>`+reportTable(['Nombre','Vigencia','Horario','Beneficio','Estado'],promos.map(p=>[p.name,p.from+' a '+p.to,p.start+'–'+p.end,promoDescription(p),promoState(p)]))+`<h2>Comisiones liquidadas</h2>`+reportTable(['Fecha','Profesional','Importe'],settlements.map(x=>[x.date,barbers[x.barber],money(x.total)]))+`<h2>Actividad registrada</h2>`+reportTable(['Fecha / hora','Acción','Perfil'],historyLog.map(x=>[stamp(x.time),x.title,x.role])))}

function qrCloseSummary(id,counted){const rows=sessionMoves(id).filter(m=>m.type==='QR (registro manual)'),received=round(rows.filter(m=>m.amount>0).reduce((n,m)=>n+m.amount,0)),returned=round(-rows.filter(m=>m.amount<0).reduce((n,m)=>n+m.amount,0)),net=round(received-returned),transfer=methodNet(id,'Transferencia (registro manual)');return `<div class="quote"><span>QR cobrado en esta caja · automático</span><strong>${money(net)}</strong><small>Cobros: ${money(received)} · Devoluciones: ${money(returned)} · ${rows.length} movimientos</small></div><div class="quote"><span>Total de cierre: efectivo contado + QR${transfer?' + otros pagos registrados':''}</span><strong>${money(round(counted+net+transfer))}</strong><small>Billetes y monedas: ${money(counted)} · QR: ${money(net)}${transfer?' · Otros pagos registrados: '+money(transfer):''}<br>Incluye el fondo inicial que permanece en efectivo. El faltante o sobrante se calcula comparando el efectivo contado con el esperado.</small></div>`}

function commissionDates(){const start=commissionPeriod==='week'?shiftDate(today,-((dayOf(today)+6)%7)):commissionPeriod==='month'?today.slice(0,7)+'-01':commissionPeriod==='all'?'0000-01-01':today;const end=commissionPeriod==='week'?shiftDate(start,6):commissionPeriod==='month'?shiftDate(shiftDate(start,32).slice(0,7)+'-01',-1):commissionPeriod==='all'?'9999-12-31':today;return {start,end}}
function commissionItems(i){const {start,end}=commissionDates();return [...appointments.filter(a=>a.barber===i&&a.status==='Completada'&&a.date>=start&&a.date<=end).map(a=>({appointment:a.id,earned:earned(a),amount:round(earned(a)-paidCommission(a.id))})),...movements.filter(m=>m.kind==='sale'&&m.barber===i&&m.date>=start&&m.date<=end).map(m=>{const paid=settlements.flatMap(s=>s.items).filter(x=>x.sale===m.id).reduce((n,x)=>n+x.amount,0);return {sale:m.id,earned:m.commissionAmount||0,amount:round((m.commissionAmount||0)-paid)}})]}
function productCommissionForm(i){if(role!=='Propietario')return;modal('Comisión de productos · '+barbers[i],field('Porcentaje por venta',input('rate','number',productRates[i]??'','required min="0" max="100" step="0.01"'))+'<p>Aplica a ventas futuras. Cada venta conserva el porcentaje aceptado. Puedes poner 0 si no corresponde comisión.</p>',f=>{const rate=Number(f.get('rate'));if(f.get('rate')===''||!Number.isFinite(rate)||rate<0||rate>100)throw Error('Indica un porcentaje de 0 a 100.');productRates[i]=rate;logAction('Comisión de productos: '+barbers[i]+' '+rate+'%');finish('Porcentaje guardado')})}
function commissionPage(){const {start,end}=commissionDates();$('#main').innerHTML=heading('Comisiones del equipo','Servicios y productos sumados por profesional.')+`<div class="toolbar"><label>Período <select onchange="commissionPeriod=this.value;commissionPage()">${[['day','Hoy'],['week','Esta semana'],['month','Este mes'],['all','Todo el historial']].map(([v,t])=>`<option value="${v}" ${v===commissionPeriod?'selected':''}>${t}</option>`).join('')}</select></label><span>${commissionPeriod==='all'?'Historial completo':start+' a '+end}</span></div><div class="cards">${barbers.map((b,i)=>{const items=commissionItems(i),services=items.filter(x=>x.appointment).reduce((n,x)=>n+x.earned,0),products=items.filter(x=>x.sale).reduce((n,x)=>n+x.earned,0),pending=items.reduce((n,x)=>n+x.amount,0);return `<article class="card"><h2>${esc(b)}</h2><strong class="price">${money(services+products)}</strong><p>Total generado en el período<br>Servicios: ${money(services)}<br>Productos: ${money(products)}<br>Liquidado: ${money(services+products-pending)}<br><b>Pendiente: ${money(pending)}</b></p><p>Productos: ${productRates[i]===undefined?'Porcentaje pendiente de configurar':productRates[i]+'%'}</p><div class="buttons"><button onclick="commissionForm(${i})">Regla de servicios</button><button onclick="productCommissionForm(${i})">Regla de productos</button><button onclick="settleForm(${i})">Liquidar período</button></div></article>`}).join('')}</div><p class="notice">Las comisiones de servicios se agrupan por fecha de atención; las de productos, por fecha de venta. No incluyen un sueldo fijo. Los cambios de porcentaje no modifican ventas ni liquidaciones anteriores.</p><h2>Liquidaciones</h2>${reportTable(['Fecha','Barbero','Total'],settlements.map(x=>[x.date,barbers[x.barber],money(x.total)]))}`}
function settleForm(i){if(role!=='Propietario')return;const items=commissionItems(i).filter(x=>x.amount!==0),total=round(items.reduce((n,x)=>n+x.amount,0));if(total<=0)return notify('No hay saldo positivo para liquidar en este período.');modal('Liquidar comisiones',`<p>${esc(barbers[i])} · <b>${money(total)}</b></p><p>Incluye servicios y ventas de productos del período seleccionado. Registra la liquidación; no transfiere dinero ni retira efectivo de caja.</p>`,()=>{settlements.push({id:uuidNumber(),date:localCashDate(),barber:i,items,total});logAction('Liquidación de servicios y productos '+barbers[i]+' · '+money(total));finish('Liquidación registrada')})}